        "question": "Read the story. Grade 2 foundation story: Mateo was at the school bus line when a younger student dropped a folder and papers scattered. Mateo Mateo stepped out of line, gathered the papers, and helped sort them by subject. In the end, the younger student smiled and found the missing homework.\n\nWhat is the story's main problem?",
