        "question": "Read the story. Grade 3 developing story: Evan was at the soccer field when his team was losing and he had not scored. Evan felt the pressure of the moment, but he passed to a teammate who had a clear shot instead of kicking from a bad angle. In the end, the teammate scored and the team cheered together.\n\nWhat is the story's main problem?",
